use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'JSON::Stream::Tiny',
    VERSION_FROM     => 'lib/JSON/Stream/Tiny.pm',
    MIN_PERL_VERSION => '5.036',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package JSON::Stream::Tiny;
use strict;
use warnings;
use v5.36;

our $VERSION = '0.01';

sub decode ($class, $text) {
    return [split /\n/, $text];
}

1;

use strict;
use warnings;
use Test::More;
use JSON::Stream::Tiny;

is(scalar @{JSON::Stream::Tiny->decode("1\n2")}, 2, 'splits');

done_testing();
